css_card_relacionado:
.img-relacionada {
  width: 100%;
  height: 180px;
  object-fit: cover;
}
.transition-hover {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.transition-hover:hover {
  transform: translateY(-3px);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.1) !important;
}
.hover-primary:hover { color: var(--nat-primary, #8FBC8F) !important; }

javascript:
try {
  const relatedContainer = document.getElementById('related-posts-container');
  const relatedGrid = document.getElementById('related-posts-grid');

  if (relatedContainer && relatedGrid) {
    const label = relatedContainer.getAttribute('data-label');
    const currentUrl = relatedContainer.getAttribute('data-url');

    if (label) {
      const feedUrl = '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=4';

      fetch(feedUrl)
        .then(r => r.json())
        .then(data => {
          const entries = data.feed.entry || [];
          let html = '';
          let count = 0;

          entries.forEach(entry => {
            let postUrl = '';
            entry.link.forEach(link => { if (link.rel === 'alternate') postUrl = link.href; });
            if (postUrl === currentUrl || count >= 3) return;

            const postTitle = entry.title.$t;
            let postImg = entry.media$thumbnail
              ? entry.media$thumbnail.url
              : 'https://placehold.co/600x400';
            postImg = postImg.replace(/\/s[0-9]+(-c)?\//g, '/w600/');

            html += `
              <div class="col-md-4 col-sm-6">
                <article class="card h-100 shadow-sm border-0 transition-hover">
                  <a href="${postUrl}">
                    <img src="${postImg}" class="card-img-top img-relacionada" alt="${postTitle}">
                  </a>
                  <div class="card-body p-3">
                    <h3 class="card-title h6 fw-bold mb-0">
                      <a href="${postUrl}" class="text-dark text-decoration-none hover-primary">${postTitle}</a>
                    </h3>
                  </div>
                </article>
              </div>`;
            count++;
          });

          if (html !== '') {
            relatedGrid.innerHTML = html;
          } else {
            relatedContainer.style.display = 'none';
          }
        })
        .catch(err => {
          console.error('Relacionadas erro:', err);
          relatedContainer.style.display = 'none';
        });
    }
  }
} catch(e) { console.error('Relacionadas:', e); }
